import{_ as a,o as t,c as r,ag as s}from"./chunks/framework.Drp2S_UI.js";const g=JSON.parse('{"title":"Canvas Editor 1.0.0 正式发布 🎉","description":"","frontmatter":{},"headers":[],"relativePath":"RELEASE_NOTES_1.0.0.md","filePath":"RELEASE_NOTES_1.0.0.md","lastUpdated":1792653875000}'),o={name:"RELEASE_NOTES_1.0.0.md"};function i(n,e,l,h,u,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<blockquote><p><strong>上游历史文档 / Upstream historical document</strong> 本文保留 Hufe921/canvas-editor 的 1.0.0 发布记录及原始链接， 不代表本 fork 的版本或已验证能力。本项目从 <code>@herberthe/canvas-editor@0.1.0</code> 独立版本线开始，当前仅支持 Canvas 页面绘制，SVG 实现暂缓。 参见<a href="./guide/fork-and-differences.html">项目关系与差异</a>。</p></blockquote><h1 id="canvas-editor-1-0-0-正式发布-🎉" tabindex="-1">Canvas Editor 1.0.0 正式发布 🎉 <a class="header-anchor" href="#canvas-editor-1-0-0-正式发布-🎉" aria-label="Permalink to &quot;Canvas Editor 1.0.0 正式发布 🎉&quot;">​</a></h1><blockquote><p><strong>历时 1723 天、139 个发布版本、1460 次提交之后,Canvas Editor 正式进入 1.0 时代。</strong></p><p>这个版本意味着,基于原生 Canvas 的富文本编辑器在 EMR(电子病历)、合同、公文、报表等对排版精度和分页有严苛要求的场景中,迈出了扎实的一步。</p></blockquote><p align="center"><a href="https://www.npmjs.com/package/@hufe921/canvas-editor" target="_blank"><img src="https://img.shields.io/npm/v/@hufe921/canvas-editor.svg?sanitize=true" alt="Version"></a><a href="https://github.com/hufe921/canvas-editor/actions" target="_blank"><img alt="Cypress Passing" src="https://github.com/hufe921/canvas-editor/workflows/cypress/badge.svg"></a><a href="https://github.com/Hufe921/canvas-editor" target="_blank"><img alt="GitHub Stars" src="https://img.shields.io/github/stars/hufe921/canvas-editor?style=social"></a></p><hr><h2 id="📌-tl-dr" tabindex="-1">📌 TL;DR <a class="header-anchor" href="#📌-tl-dr" aria-label="Permalink to &quot;📌 TL;DR&quot;">​</a></h2><ul><li>⭐ <strong>表格分页这个困扰社区 4 年多的核心难题(<a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a>)得到系统性解决</strong> —— 放弃数据层物理切割,改为渲染层切分,跨页表格的合并、光标选区、输入实现正确联动。</li><li>✨ 八大重点能力落地:<strong>留痕模式、控件级联与校验(表达式)、控件嵌套、多栏布局、标尺、多级有序列表、区域子文档、宏</strong>。</li><li>🛠 API 趋于稳定,后续将遵循 SemVer:1.x 期间不会有破坏性变更。</li></ul><hr><h2 id="🎯-为什么是-1-0-为什么是现在" tabindex="-1">🎯 为什么是 1.0?为什么是现在? <a class="header-anchor" href="#🎯-为什么是-1-0-为什么是现在" aria-label="Permalink to &quot;🎯 为什么是 1.0?为什么是现在?&quot;">​</a></h2><p>Canvas Editor 从 2021 年 11 月 12 日第一次提交到现在,已经走过了 1723 天。在这个过程中,我一直在追问自己一个问题:</p><blockquote><p><strong>&quot;基于 Canvas 的富文本编辑器,真的能替代 contenteditable 用于严肃的文档场景吗?&quot;</strong></p></blockquote><p>1.0.0 之前,答案是&quot;接近可以,但还有几块硬骨头&quot;。1.0.0 之后,我想可以比较有底气地说:<strong>在多数严肃文档场景下,可用了</strong>。</p><p>判断依据有四:</p><table tabindex="0"><thead><tr><th>维度</th><th>1.0 之前</th><th>1.0.0</th></tr></thead><tbody><tr><td><strong>表格</strong></td><td>单页可用,跨页体验破碎</td><td>渲染层分页、列宽同步、行高自适应大幅完善</td></tr><tr><td><strong>控件</strong></td><td>单层、无校验</td><td>支持嵌套、级联表达式、表单校验</td></tr><tr><td><strong>排版</strong></td><td>基础分页</td><td>多栏布局、图片环绕、标尺、修订留痕</td></tr><tr><td><strong>API 稳定性</strong></td><td>持续演进</td><td>冻结核心 API,进入 SemVer 严格管理</td></tr></tbody></table><p>**表格分页是最关键的一块拼图。**它是社区呼声最高、技术难度最大的特性,也是 1.0 迟迟没有发布的主要原因。它落地之后,最难的渲染路径基本走通,后续迭代会从&quot;修关键 bug&quot;转向&quot;扩展能力&quot;。</p><hr><h2 id="⭐-头号特性-表格分页-41" tabindex="-1">⭐ 头号特性:表格分页 <a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a> <a class="header-anchor" href="#⭐-头号特性-表格分页-41" aria-label="Permalink to &quot;⭐ 头号特性:表格分页 [#41](https://github.com/Hufe921/canvas-editor/issues/41)&quot;">​</a></h2><p><a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">Issue #41</a> 提出于 <strong>2022 年 4 月 28 日</strong>,距今 1556 天,积累了 39 条讨论,是仓库里生命周期最长的 issue 之一。最初的反馈只有一句话:</p><blockquote><p>跨页表格在修改列宽的时候,不能够同步。</p></blockquote><p>这背后是整个编辑器最复杂的渲染路径之一:行要在页边界动态拆分、各页列宽必须严格一致、含图片/列表/子表格的单元格行高要自适应、光标和选区要在分页后正确响应。</p><h3 id="方案演进-从-数据层拆分-到-渲染层切分" tabindex="-1">方案演进:从&quot;数据层拆分&quot;到&quot;渲染层切分&quot; <a class="header-anchor" href="#方案演进-从-数据层拆分-到-渲染层切分" aria-label="Permalink to &quot;方案演进:从&quot;数据层拆分&quot;到&quot;渲染层切分&quot;&quot;">​</a></h3><p><strong>① 数据层拆分方案(2024.03 前后)</strong></p><p>最早的思路是:把超出当前页的非跨行<strong>行</strong>拆出来,形成一个新表格;渲染时先合并再拆分,保存数据时再合并。这个方案解决了&quot;能分页&quot;,但天花板很明显分页后的表格一变就无法还原,合并行单元格跨页失效、单格超高不跨页、控件跨行丢内容等边界问题在 issue 里被陆续反馈出来。本质原因是:<strong>数据被物理切成了两段,之后所有操作都要为&quot;同步两段状态&quot;付出代价</strong>。</p><p><strong>② 社区协作与 POC 验证(2025)</strong></p><p>期间 <a href="https://github.com/the-lemonboy" target="_blank" rel="noreferrer">@the-lemonboy</a>、<a href="https://github.com/sLin90" target="_blank" rel="noreferrer">@sLin90</a>、<a href="https://github.com/ThunderYu" target="_blank" rel="noreferrer">@ThunderYu</a> 等社区同学贡献了思路和 PR。结合他们的实现思路,我在 <code>poc/table-paging</code> 分支做了可行性验证,并梳理出完整的待办清单:跨页中文输入、跨页删除/书写/方向键光标处理、选区跨页拖蓝、控件跨页、复合元素跨页、边界处理。</p><p><strong>③ 渲染层切分方案(2026.07,本次落地)</strong></p><p>最终完成了一次核心思路的转换:<strong>放弃数据层面的物理切割,仅在渲染层面进行切分</strong>。数据结构始终保持完整,只在 Canvas 绘制阶段计算分页截断位置。这个&quot;降维&quot;处理,让之前大量的状态同步类 bug 自然消解,性能和稳定性也随之提升。</p><h3 id="本次改动-feat-optimize-table-pagination-41" tabindex="-1">本次改动(<code>feat: optimize table pagination #41</code>) <a class="header-anchor" href="#本次改动-feat-optimize-table-pagination-41" aria-label="Permalink to &quot;本次改动(`feat: optimize table pagination #41`)&quot;">​</a></h3><ul><li>新增 <code>TablePaging</code> 分页计算模块(约 740 行):负责跨页截断点的测量与计算</li><li>重写 <code>TableParticle</code> 表格渲染逻辑(约 510 行改动):渲染期按截断点切分绘制</li><li><code>Position</code> 光标定位系统跨页适配(约 500 行改动):覆盖跨页中文输入、删除/书写/方向键光标、选区跨页拖蓝</li><li>配套 <strong>1600+ 行单元测试</strong>(<code>tests/core/draw/tablePaging.test.ts</code>)</li><li>合计 <strong>3373 行新增代码</strong></li></ul><p>同时配套落地:</p><ul><li>✅ 含富内容/跨行(<code>rowspan</code>)单元格的行高自适应</li><li>✅ 表格宽度自适应内容与页面(<a href="https://github.com/Hufe921/canvas-editor/issues/1387" target="_blank" rel="noreferrer">#1387</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1453" target="_blank" rel="noreferrer">#1453</a>)</li><li>✅ 跨页表格列宽同步</li></ul><p><strong>这是一次从底层思路出发的重写,而不只是打补丁。</strong> 分页场景千变万化,如果你在使用过程中遇到新的边界 case,欢迎继续在 <a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a> 下反馈。</p><hr><h2 id="🎁-1-0-重点功能巡礼" tabindex="-1">🎁 1.0 重点功能巡礼 <a class="header-anchor" href="#🎁-1-0-重点功能巡礼" aria-label="Permalink to &quot;🎁 1.0 重点功能巡礼&quot;">​</a></h2><h3 id="🖋-留痕模式-trace-mode-312" tabindex="-1">🖋 留痕模式(Trace Mode)<a href="https://github.com/Hufe921/canvas-editor/issues/312" target="_blank" rel="noreferrer">#312</a> <a class="header-anchor" href="#🖋-留痕模式-trace-mode-312" aria-label="Permalink to &quot;🖋 留痕模式(Trace Mode)[#312](https://github.com/Hufe921/canvas-editor/issues/312)&quot;">​</a></h3><p>类似 Word 的&quot;修订&quot;:开启后,所有增删改都会留下痕迹——删除的内容以删除线标注,悬停可查看<strong>作者与时间</strong>,并可控制痕迹的可见性。病历修改留痕、合同审阅、公文批改,这类强合规场景可以少造很多轮子。</p><h3 id="🔗-控件级联与校验-表达式-671" tabindex="-1">🔗 控件级联与校验(表达式)<a href="https://github.com/Hufe921/canvas-editor/issues/671" target="_blank" rel="noreferrer">#671</a> <a class="header-anchor" href="#🔗-控件级联与校验-表达式-671" aria-label="Permalink to &quot;🔗 控件级联与校验(表达式)[#671](https://github.com/Hufe921/canvas-editor/issues/671)&quot;">​</a></h3><p>Select / Radio / Checkbox / 文本控件之间可以建立<strong>父子联动与校验规则</strong>,并支持表达式自动计算:</p><ul><li>输入身高 170cm、体重 100kg,<strong>BMI 自动算出 34.6</strong>,并联动显示&quot;肥胖干预建议&quot;</li><li>选择&quot;有高血压&quot;,自动带出&quot;高血压分级&quot;必填项</li><li>提交前对必填、格式进行校验</li></ul><p>一份电子病历模板,从此可以自带一部分&quot;业务逻辑&quot;。</p><h3 id="🪆-控件嵌套-425" tabindex="-1">🪆 控件嵌套 <a href="https://github.com/Hufe921/canvas-editor/issues/425" target="_blank" rel="noreferrer">#425</a> <a class="header-anchor" href="#🪆-控件嵌套-425" aria-label="Permalink to &quot;🪆 控件嵌套 [#425](https://github.com/Hufe921/canvas-editor/issues/425)&quot;">​</a></h3><p>控件内部可以再嵌套富文本与其他控件,复杂表单结构(如&quot;诊断标签&quot;里套&quot;分期选择&quot;)可以更自然地表达。</p><h3 id="📰-多栏布局-1237" tabindex="-1">📰 多栏布局 <a href="https://github.com/Hufe921/canvas-editor/issues/1237" target="_blank" rel="noreferrer">#1237</a> <a class="header-anchor" href="#📰-多栏布局-1237" aria-label="Permalink to &quot;📰 多栏布局 [#1237](https://github.com/Hufe921/canvas-editor/issues/1237)&quot;">​</a></h3><p>像 Word 一样的分栏排版:主诉、现病史一栏,辅助检查、门诊诊断一栏,内容跨栏自动流动,缩放、改纸宽后栏位自动重排。</p><h3 id="🖼-图片四周环绕-554" tabindex="-1">🖼 图片四周环绕 <a href="https://github.com/Hufe921/canvas-editor/issues/554" target="_blank" rel="noreferrer">#554</a> <a class="header-anchor" href="#🖼-图片四周环绕-554" aria-label="Permalink to &quot;🖼 图片四周环绕 [#554](https://github.com/Hufe921/canvas-editor/issues/554)&quot;">​</a></h3><p>浮动图片支持文字四周环绕——手写签名图插进段落中间,文字自动绕排,随内容增删实时调整。</p><h3 id="📏-标尺-438" tabindex="-1">📏 标尺 <a href="https://github.com/Hufe921/canvas-editor/issues/438" target="_blank" rel="noreferrer">#438</a> <a class="header-anchor" href="#📏-标尺-438" aria-label="Permalink to &quot;📏 标尺 [#438](https://github.com/Hufe921/canvas-editor/issues/438)&quot;">​</a></h3><p>水平 + 垂直双标尺,刻度随缩放联动,页边距、缩进一目了然,排版对齐不再靠猜。</p><h3 id="🔢-多级有序列表-440" tabindex="-1">🔢 多级有序列表 <a href="https://github.com/Hufe921/canvas-editor/issues/440" target="_blank" rel="noreferrer">#440</a> <a class="header-anchor" href="#🔢-多级有序列表-440" aria-label="Permalink to &quot;🔢 多级有序列表 [#440](https://github.com/Hufe921/canvas-editor/issues/440)&quot;">​</a></h3><p>子列表编号正确联动:一级&quot;1. 高血压&quot;下挂&quot;1. 高血压1级 / 2. 原发性高血压&quot;,增删条目后全层级自动重排。</p><h3 id="📑-区域子文档-area" tabindex="-1">📑 区域子文档(Area) <a class="header-anchor" href="#📑-区域子文档-area" aria-label="Permalink to &quot;📑 区域子文档(Area)&quot;">​</a></h3><p>一份文档内可划分多个<strong>独立区域</strong>:主病历 + 补充病历各有独立的编辑上下文、占位符、只读与隐藏规则,区域甚至可以放进表格单元格 <a href="https://github.com/Hufe921/canvas-editor/issues/1317" target="_blank" rel="noreferrer">#1317</a>。配套的 <code>executeInsertArea</code> / <code>executeLocationArea</code> / <code>executeSetAreaValue</code> / <code>executeDeleteArea</code> 系列 API 让&quot;一份文档、多段分管&quot;成为可能。</p><h3 id="⏺-宏录制与回放-478" tabindex="-1">⏺ 宏录制与回放 <a href="https://github.com/Hufe921/canvas-editor/issues/478" target="_blank" rel="noreferrer">#478</a> <a class="header-anchor" href="#⏺-宏录制与回放-478" aria-label="Permalink to &quot;⏺ 宏录制与回放 [#478](https://github.com/Hufe921/canvas-editor/issues/478)&quot;">​</a></h3><p>录制一段操作序列(插入控件、设置样式、填充数据),一键回放,适合批量生成与自动化测试。</p><h3 id="🆚-文档对比-api-1024" tabindex="-1">🆚 文档对比 API <a href="https://github.com/Hufe921/canvas-editor/issues/1024" target="_blank" rel="noreferrer">#1024</a> <a class="header-anchor" href="#🆚-文档对比-api-1024" aria-label="Permalink to &quot;🆚 文档对比 API [#1024](https://github.com/Hufe921/canvas-editor/issues/1024)&quot;">​</a></h3><p>新增 compare 能力,两个版本文档的差异一目了然,配合留痕模式可以构成一个基本的审阅闭环。</p><hr><h2 id="📅-近三年重点需求回顾-2023-08-→-2026-07" tabindex="-1">📅 近三年重点需求回顾(2023.08 → 2026.07) <a class="header-anchor" href="#📅-近三年重点需求回顾-2023-08-→-2026-07" aria-label="Permalink to &quot;📅 近三年重点需求回顾(2023.08 → 2026.07)&quot;">​</a></h2><p>1.0 不是一蹴而就的。近三年 <strong>781 次提交、256 个修复、479 个 issue 被处理</strong>,下面是社区呼声最高的几条主线:</p><h3 id="表格体系-投入最大的一条线" tabindex="-1">表格体系(投入最大的一条线) <a class="header-anchor" href="#表格体系-投入最大的一条线" aria-label="Permalink to &quot;表格体系(投入最大的一条线)&quot;">​</a></h3><ul><li>表格分页优化 <a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a> ⭐</li><li>表格宽度自适应内容与页面 <a href="https://github.com/Hufe921/canvas-editor/issues/1387" target="_blank" rel="noreferrer">#1387</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1453" target="_blank" rel="noreferrer">#1453</a></li><li>表格嵌套操作 <a href="https://github.com/Hufe921/canvas-editor/issues/650" target="_blank" rel="noreferrer">#650</a>、拆分单元格 <a href="https://github.com/Hufe921/canvas-editor/issues/826" target="_blank" rel="noreferrer">#826</a>、合并保留内容 <a href="https://github.com/Hufe921/canvas-editor/issues/932" target="_blank" rel="noreferrer">#932</a></li><li>快速插入行/列工具、虚线边框 <a href="https://github.com/Hufe921/canvas-editor/issues/858" target="_blank" rel="noreferrer">#858</a>、边框颜色与宽度 <a href="https://github.com/Hufe921/canvas-editor/issues/897" target="_blank" rel="noreferrer">#897</a></li><li>表格可超出正文边界 <a href="https://github.com/Hufe921/canvas-editor/issues/1232" target="_blank" rel="noreferrer">#1232</a>、自动生成 colgroup <a href="https://github.com/Hufe921/canvas-editor/issues/1404" target="_blank" rel="noreferrer">#1404</a></li></ul><h3 id="控件体系-表单化" tabindex="-1">控件体系(表单化) <a class="header-anchor" href="#控件体系-表单化" aria-label="Permalink to &quot;控件体系(表单化)&quot;">​</a></h3><ul><li>控件级联与校验 <a href="https://github.com/Hufe921/canvas-editor/issues/671" target="_blank" rel="noreferrer">#671</a>、控件嵌套 <a href="https://github.com/Hufe921/canvas-editor/issues/425" target="_blank" rel="noreferrer">#425</a></li><li>数字控件(内置计算器)<a href="https://github.com/Hufe921/canvas-editor/issues/925" target="_blank" rel="noreferrer">#925</a>、Select 多选与输入 <a href="https://github.com/Hufe921/canvas-editor/issues/518" target="_blank" rel="noreferrer">#518</a>、日期控件年月面板 <a href="https://github.com/Hufe921/canvas-editor/issues/1256" target="_blank" rel="noreferrer">#1256</a></li><li>控件分组 <a href="https://github.com/Hufe921/canvas-editor/issues/1259" target="_blank" rel="noreferrer">#1259</a>、设计模式 <a href="https://github.com/Hufe921/canvas-editor/issues/795" target="_blank" rel="noreferrer">#795</a>、批量设置属性 <a href="https://github.com/Hufe921/canvas-editor/issues/1037" target="_blank" rel="noreferrer">#1037</a></li></ul><h3 id="排版与版面" tabindex="-1">排版与版面 <a class="header-anchor" href="#排版与版面" aria-label="Permalink to &quot;排版与版面&quot;">​</a></h3><ul><li>多栏布局 <a href="https://github.com/Hufe921/canvas-editor/issues/1237" target="_blank" rel="noreferrer">#1237</a>、图片环绕 <a href="https://github.com/Hufe921/canvas-editor/issues/554" target="_blank" rel="noreferrer">#554</a>、标尺 <a href="https://github.com/Hufe921/canvas-editor/issues/438" target="_blank" rel="noreferrer">#438</a></li><li>多级有序列表 <a href="https://github.com/Hufe921/canvas-editor/issues/440" target="_blank" rel="noreferrer">#440</a>、页面边框、行号 <a href="https://github.com/Hufe921/canvas-editor/issues/734" target="_blank" rel="noreferrer">#734</a></li><li>单页隐藏页眉页脚 <a href="https://github.com/Hufe921/canvas-editor/issues/778" target="_blank" rel="noreferrer">#778</a>、页眉页脚可编辑</li></ul><h3 id="区域子文档-area" tabindex="-1">区域子文档(Area) <a class="header-anchor" href="#区域子文档-area" aria-label="Permalink to &quot;区域子文档(Area)&quot;">​</a></h3><ul><li>区域占位符 <a href="https://github.com/Hufe921/canvas-editor/issues/1076" target="_blank" rel="noreferrer">#1076</a>、区域可删除/隐藏 <a href="https://github.com/Hufe921/canvas-editor/issues/1014" target="_blank" rel="noreferrer">#1014</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1139" target="_blank" rel="noreferrer">#1139</a></li><li>区域系列 API、表格单元格内区域 <a href="https://github.com/Hufe921/canvas-editor/issues/1317" target="_blank" rel="noreferrer">#1317</a></li></ul><h3 id="效率工具" tabindex="-1">效率工具 <a class="header-anchor" href="#效率工具" aria-label="Permalink to &quot;效率工具&quot;">​</a></h3><ul><li>宏录制回放 <a href="https://github.com/Hufe921/canvas-editor/issues/478" target="_blank" rel="noreferrer">#478</a>、格式刷增强 <a href="https://github.com/Hufe921/canvas-editor/issues/446" target="_blank" rel="noreferrer">#446</a></li><li>正则搜索 <a href="https://github.com/Hufe921/canvas-editor/issues/1308" target="_blank" rel="noreferrer">#1308</a>、选区内搜索 <a href="https://github.com/Hufe921/canvas-editor/issues/1336" target="_blank" rel="noreferrer">#1336</a>、忽略大小写 <a href="https://github.com/Hufe921/canvas-editor/issues/1316" target="_blank" rel="noreferrer">#1316</a></li><li>图片裁剪 <a href="https://github.com/Hufe921/canvas-editor/issues/1327" target="_blank" rel="noreferrer">#1327</a>、图片标题 <a href="https://github.com/Hufe921/canvas-editor/issues/1326" target="_blank" rel="noreferrer">#1326</a>、放大镜 <a href="https://github.com/Hufe921/canvas-editor/issues/1391" target="_blank" rel="noreferrer">#1391</a>、涂鸦模式 <a href="https://github.com/Hufe921/canvas-editor/issues/992" target="_blank" rel="noreferrer">#992</a></li></ul><h3 id="企业级能力" tabindex="-1">企业级能力 <a class="header-anchor" href="#企业级能力" aria-label="Permalink to &quot;企业级能力&quot;">​</a></h3><ul><li>留痕模式 <a href="https://github.com/Hufe921/canvas-editor/issues/312" target="_blank" rel="noreferrer">#312</a>、文档对比 <a href="https://github.com/Hufe921/canvas-editor/issues/1024" target="_blank" rel="noreferrer">#1024</a></li><li>水印:图片水印 <a href="https://github.com/Hufe921/canvas-editor/issues/1043" target="_blank" rel="noreferrer">#1043</a>、图层配置 <a href="https://github.com/Hufe921/canvas-editor/issues/1386" target="_blank" rel="noreferrer">#1386</a>、重复平铺 <a href="https://github.com/Hufe921/canvas-editor/issues/665" target="_blank" rel="noreferrer">#665</a></li><li>无障碍(屏幕阅读器)<a href="https://github.com/Hufe921/canvas-editor/issues/1420" target="_blank" rel="noreferrer">#1420</a>、国际化 <a href="https://github.com/Hufe921/canvas-editor/issues/1159" target="_blank" rel="noreferrer">#1159</a></li><li>打印:离屏打印、过滤空控件/隐藏元素 <a href="https://github.com/Hufe921/canvas-editor/issues/1429" target="_blank" rel="noreferrer">#1429</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1385" target="_blank" rel="noreferrer">#1385</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1410" target="_blank" rel="noreferrer">#1410</a></li></ul><hr><h2 id="🐛-bug-fixes-自-0-9-137" tabindex="-1">🐛 Bug Fixes(自 0.9.137) <a class="header-anchor" href="#🐛-bug-fixes-自-0-9-137" aria-label="Permalink to &quot;🐛 Bug Fixes(自 0.9.137)&quot;">​</a></h2><ul><li>修复含跨行单元格(<code>rowspan</code>)的高内容时行高计算错误</li><li>修复控件级联恢复时成员状态同步与高亮错误</li><li>修复非激活态控件输入前未正确激活的问题 <a href="https://github.com/Hufe921/canvas-editor/issues/1443" target="_blank" rel="noreferrer">#1443</a></li></ul><p>完整提交列表请见 <a href="https://github.com/Hufe921/canvas-editor/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a>。</p><hr><h2 id="📦-升级指南" tabindex="-1">📦 升级指南 <a class="header-anchor" href="#📦-升级指南" aria-label="Permalink to &quot;📦 升级指南&quot;">​</a></h2><p>如果你正在使用 0.9.x:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @hufe921/canvas-editor@1.0.0</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @hufe921/canvas-editor@1.0.0</span></span></code></pre></div><p><strong>1.0.0 没有引入破坏性 API 变更</strong>,绝大多数用户可以无缝升级。建议关注以下两点:</p><ol><li><strong>表格分页行为变化</strong>:跨页表格的渲染结果会与 0.9.x 不同(变得更&quot;正确&quot;)。如果你的业务对表格视觉快照有截图断言,需要更新测试基线。</li><li><strong>控件级联校验是可选启用</strong>:不会自动影响现有控件,需要显式配置。</li></ol><p>如果升级遇到任何问题,欢迎在 <a href="https://github.com/Hufe921/canvas-editor/discussions" target="_blank" rel="noreferrer">Discussions</a> 提问,或在 <a href="https://github.com/Hufe921/canvas-editor/issues/new?template=bug_report.yml" target="_blank" rel="noreferrer">Issues</a> 提交 bug。</p><hr><h2 id="🗺-路线图" tabindex="-1">🗺 路线图 <a class="header-anchor" href="#🗺-路线图" aria-label="Permalink to &quot;🗺 路线图&quot;">​</a></h2><p>1.0 之后,方向从&quot;补关键能力&quot;转向&quot;扩展生态&quot;:</p><ol><li><strong>大文本渲染性能</strong>:面向超长文档的测量与绘制优化,大文档下保持流畅编辑</li><li><strong>渲染层独立</strong>:渲染与内核解耦,同一份文档模型可输出到 SVG、PDF、DOM 等多种渲染目标</li><li><strong>多光标选区</strong>:支持多处光标与选区,为协作编辑和批量操作打底</li><li><strong>协作编辑能力</strong>:多人实时协作、光标同步与冲突合并(Yjs / CRDT 路线评估中)</li></ol><p>如果你对某个方向感兴趣,欢迎在对应 issue 下 +1 或参与讨论——<strong>呼声最高的特性会优先排期</strong>。</p><hr><h2 id="✍️-一些数据" tabindex="-1">✍️ 一些数据 <a class="header-anchor" href="#✍️-一些数据" aria-label="Permalink to &quot;✍️ 一些数据&quot;">​</a></h2><p>Canvas Editor 是我在业余时间维护的个人项目,过去 1723 天:</p><ul><li><p><strong>1460 次提交</strong>,其中近 3 年 781 次;处理了 <strong>479 个 issue</strong>,发布了 <strong>139 个版本</strong></p></li><li><p>提交最多的时段是<strong>晚上 9 点到 10 点</strong>(224 + 150 次)——下班之后的时间</p></li><li><p><strong>162 次提交发生在深夜 10 点以后</strong>,<strong>245 次发生在周末</strong></p><p>1.0 的落地也离不开社区:<a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a> 的最终方案,吸收了多位社区同学 PR 中的思路,并在 POC 分支经过了公开验证;最后的重构阶段,也借助了 AI 编程工具提升效率。这也是开源有意思的地方——一个问题挂了四年,最后是很多人一起把它推过终点线的。</p></li></ul><p>如果这个项目帮到过你,一个 Star、一次转发,都是很好的支持。</p><hr><h2 id="💛-个人赞助" tabindex="-1">💛 个人赞助 <a class="header-anchor" href="#💛-个人赞助" aria-label="Permalink to &quot;💛 个人赞助&quot;">​</a></h2><p>Canvas Editor 是一个由个人发起、近 5 年利用业余时间持续投入的开源项目,始终遵循 MIT 协议免费开源。1.0 是一个里程碑,但也是一个新的起点——上面列出的路线图每一项都需要相当大的投入。</p><p>如果你或你的公司在使用 Canvas Editor,并希望项目长期健康发展,欢迎赞助:</p><ul><li><strong>GitHub Sponsors</strong>:<a href="https://hufe.club/donate.jpg" target="_blank" rel="noreferrer">https://hufe.club/donate.jpg</a></li></ul><p>哪怕是一次性的小额赞助,也是对持续维护最直接的鼓励。当然,Star、转发、认真的 issue 和 PR,同样珍贵。</p><hr><h2 id="🙏-致谢" tabindex="-1">🙏 致谢 <a class="header-anchor" href="#🙏-致谢" aria-label="Permalink to &quot;🙏 致谢&quot;">​</a></h2><p>感谢过去 4 年多里每一位提交 issue、提 PR、在群里答疑、写文章推荐、默默 star 的朋友。</p><p>Canvas Editor 的下一个篇章,希望继续与你同行。</p><hr><p align="center"><strong>Canvas Editor 1.0.0</strong><br><a href="https://github.com/Hufe921/canvas-editor">⭐ GitHub</a> · <a href="https://hufe.club/canvas-editor">🚀 Live Demo</a> · <a href="https://hufe.club/canvas-editor-docs">📖 文档</a> · <a href="https://hufe.club/donate.jpg">💛 赞助</a></p><hr><hr><h1 id="canvas-editor-1-0-0-released-🎉-english" tabindex="-1">Canvas Editor 1.0.0 Released 🎉 (English) <a class="header-anchor" href="#canvas-editor-1-0-0-released-🎉-english" aria-label="Permalink to &quot;Canvas Editor 1.0.0 Released 🎉 (English)&quot;">​</a></h1><blockquote><p><strong>After 1,723 days, 139 releases, and 1,460 commits, Canvas Editor officially enters the 1.0 era.</strong></p><p>This release is a solid step forward for canvas-based rich text editing in document scenarios with strict layout and pagination requirements — EMR (electronic medical records), contracts, official documents, and reports.</p></blockquote><h2 id="📌-tl-dr-1" tabindex="-1">📌 TL;DR <a class="header-anchor" href="#📌-tl-dr-1" aria-label="Permalink to &quot;📌 TL;DR&quot;">​</a></h2><ul><li>⭐ <strong>Table pagination — the #1 community pain point for over 4 years (<a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a>) — has been systematically addressed</strong> by moving from data-level splitting to render-level slicing: cross-page table merging, cursor/selection, and input now work correctly together.</li><li>✨ Eight headline features: <strong>Trace Mode, control cascade &amp; validation (expressions), control nesting, multi-column layout, rulers, multi-level ordered lists, area sub-documents, and macros</strong>.</li><li>🛠 The API is stabilizing and follows SemVer: no breaking changes throughout 1.x.</li></ul><h2 id="🎯-why-1-0-why-now" tabindex="-1">🎯 Why 1.0? Why now? <a class="header-anchor" href="#🎯-why-1-0-why-now" aria-label="Permalink to &quot;🎯 Why 1.0? Why now?&quot;">​</a></h2><p>Since the first commit on November 12, 2021 — 1,723 days ago — one question has driven this project:</p><blockquote><p><strong>&quot;Can a Canvas-based rich text editor truly replace contenteditable for serious document scenarios?&quot;</strong></p></blockquote><p>Before 1.0.0, the answer was &quot;almost, with a few hard nuts to crack.&quot; After 1.0.0, I can say with reasonable confidence: <strong>for most serious document scenarios, yes, it&#39;s ready to use</strong>.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Before 1.0</th><th>1.0.0</th></tr></thead><tbody><tr><td><strong>Tables</strong></td><td>Usable on one page, broken across pages</td><td>Render-level pagination, column sync, adaptive row heights much improved</td></tr><tr><td><strong>Controls</strong></td><td>Single-level, no validation</td><td>Nesting, cascade expressions, form validation</td></tr><tr><td><strong>Layout</strong></td><td>Basic pagination</td><td>Multi-column, image wrapping, rulers, trace mode</td></tr><tr><td><strong>API stability</strong></td><td>Constantly evolving</td><td>Core API frozen under strict SemVer</td></tr></tbody></table><p><strong>Table pagination is the most critical piece of the puzzle.</strong> It is the community&#39;s most requested and technically hardest feature, and the main reason 1.0 took this long. With it landed, the hardest rendering path is essentially unblocked, and future iterations shift from &quot;fixing critical bugs&quot; to &quot;expanding capabilities.&quot;</p><h2 id="⭐-headline-table-pagination-41" tabindex="-1">⭐ Headline: Table Pagination <a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a> <a class="header-anchor" href="#⭐-headline-table-pagination-41" aria-label="Permalink to &quot;⭐ Headline: Table Pagination [#41](https://github.com/Hufe921/canvas-editor/issues/41)&quot;">​</a></h2><p><a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">Issue #41</a> was filed on <strong>April 28, 2022</strong> — 1,556 days ago — and has accumulated 39 comments, making it one of the longest-lived issues in the repo. The original report was deceptively simple:</p><blockquote><p>When a table spans pages, changing column widths does not stay in sync.</p></blockquote><p>Behind it lies one of the most complex rendering paths in the editor: rows must split dynamically at page boundaries, column widths must stay strictly aligned across pages, cells containing images/lists/nested tables need adaptive heights, and cursor and selection must respond correctly after pagination.</p><h3 id="evolution-from-data-level-splitting-to-render-level-slicing" tabindex="-1">Evolution: from data-level splitting to render-level slicing <a class="header-anchor" href="#evolution-from-data-level-splitting-to-render-level-slicing" aria-label="Permalink to &quot;Evolution: from data-level splitting to render-level slicing&quot;">​</a></h3><p><strong>① Data-level splitting (around 2024.03)</strong></p><p>The first approach: physically split overflow non-spanning rows into a <em>new table</em>, re-merging at render time and merging again when saving. This delivered &quot;it paginates,&quot; but the ceiling was obvious — once a paginated table changed, it could not be restored; edge cases such as merged-row cells failing to cross pages, over-tall single cells not paginating, and controls losing rows across pages kept being reported in the issue. The root cause: <strong>once data is physically cut in two, every operation pays the cost of synchronizing two pieces of state</strong>.</p><p><strong>② Community collaboration &amp; POC (2025)</strong></p><p>Along the way, community members including <a href="https://github.com/the-lemonboy" target="_blank" rel="noreferrer">@the-lemonboy</a>, <a href="https://github.com/sLin90" target="_blank" rel="noreferrer">@sLin90</a> and <a href="https://github.com/ThunderYu" target="_blank" rel="noreferrer">@ThunderYu</a> contributed ideas and PRs. Building on their approaches, I ran a feasibility proof on the <code>poc/table-paging</code> branch and laid out a full checklist: cross-page IME input, cross-page cursor behavior (delete/type/arrow keys), cross-page selection, controls across pages, composite elements across pages, and boundary handling.</p><p><strong>③ Render-level slicing (2026.07, shipped)</strong></p><p>The final solution is a shift in core thinking: <strong>no physical cutting at the data layer — slice only at render time</strong>. The document data always stays intact; pagination breakpoints are computed only during the Canvas drawing phase. This &quot;dimensionality reduction&quot; made most state-synchronization bugs simply disappear, with performance and stability improving alongside.</p><h3 id="the-change-itself-feat-optimize-table-pagination-41" tabindex="-1">The change itself (<code>feat: optimize table pagination #41</code>) <a class="header-anchor" href="#the-change-itself-feat-optimize-table-pagination-41" aria-label="Permalink to &quot;The change itself (`feat: optimize table pagination #41`)&quot;">​</a></h3><ul><li>New <code>TablePaging</code> module (~740 lines): measures and computes page breakpoints</li><li><code>TableParticle</code> rendering rewritten (~510 lines changed): draws sliced by breakpoint at render time</li><li><code>Position</code> cursor system adapted for cross-page behavior (~500 lines changed): IME input, delete/type/arrow-key cursor, cross-page selection</li><li><strong>1,600+ lines of unit tests</strong> (<code>tests/core/draw/tablePaging.test.ts</code>)</li><li><strong>3,373 lines added</strong> in total</li></ul><p>Shipped alongside:</p><ul><li>✅ Adaptive row heights for cells with tall/<code>rowspan</code> content</li><li>✅ Table width auto-fits content and page (<a href="https://github.com/Hufe921/canvas-editor/issues/1387" target="_blank" rel="noreferrer">#1387</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1453" target="_blank" rel="noreferrer">#1453</a>)</li><li>✅ Column width sync across pages</li></ul><p><strong>This is a ground-up rewrite, not a patch.</strong> Pagination scenarios vary endlessly — if you hit new edge cases, please report them under <a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a>.</p><h2 id="🎁-feature-tour" tabindex="-1">🎁 Feature Tour <a class="header-anchor" href="#🎁-feature-tour" aria-label="Permalink to &quot;🎁 Feature Tour&quot;">​</a></h2><h3 id="🖋-trace-mode-312" tabindex="-1">🖋 Trace Mode (<a href="https://github.com/Hufe921/canvas-editor/issues/312" target="_blank" rel="noreferrer">#312</a>) <a class="header-anchor" href="#🖋-trace-mode-312" aria-label="Permalink to &quot;🖋 Trace Mode ([#312](https://github.com/Hufe921/canvas-editor/issues/312))&quot;">​</a></h3><p>Word-style track changes: every insertion, deletion, and edit leaves a trace — deletions shown with strikethrough, author &amp; timestamp on hover, with visibility control. Compliance-heavy scenarios like medical-record review, contract review, and official-document markup can skip a lot of wheel-reinventing.</p><h3 id="🔗-control-cascade-validation-expressions-671" tabindex="-1">🔗 Control Cascade &amp; Validation (expressions) (<a href="https://github.com/Hufe921/canvas-editor/issues/671" target="_blank" rel="noreferrer">#671</a>) <a class="header-anchor" href="#🔗-control-cascade-validation-expressions-671" aria-label="Permalink to &quot;🔗 Control Cascade &amp; Validation (expressions) ([#671](https://github.com/Hufe921/canvas-editor/issues/671))&quot;">​</a></h3><p>Select / Radio / Checkbox / Text controls can form <strong>parent-child linkage and validation rules</strong>, with expression-based auto-calculation:</p><ul><li>Enter height 170cm and weight 100kg — <strong>BMI computes to 34.6 automatically</strong>, with linked &quot;obesity intervention advice&quot;</li><li>Selecting &quot;has hypertension&quot; automatically brings up the required &quot;hypertension grade&quot; field</li><li>Required-field and format validation before submit</li></ul><p>A medical-record template can now carry part of its own &quot;business logic.&quot;</p><h3 id="🪆-control-nesting-425" tabindex="-1">🪆 Control Nesting (<a href="https://github.com/Hufe921/canvas-editor/issues/425" target="_blank" rel="noreferrer">#425</a>) <a class="header-anchor" href="#🪆-control-nesting-425" aria-label="Permalink to &quot;🪆 Control Nesting ([#425](https://github.com/Hufe921/canvas-editor/issues/425))&quot;">​</a></h3><p>Controls can nest rich text and other controls, so complex form structures (e.g. a &quot;staging selector&quot; inside a &quot;diagnosis tag&quot;) can be expressed naturally.</p><h3 id="📰-multi-column-layout-1237" tabindex="-1">📰 Multi-column Layout (<a href="https://github.com/Hufe921/canvas-editor/issues/1237" target="_blank" rel="noreferrer">#1237</a>) <a class="header-anchor" href="#📰-multi-column-layout-1237" aria-label="Permalink to &quot;📰 Multi-column Layout ([#1237](https://github.com/Hufe921/canvas-editor/issues/1237))&quot;">​</a></h3><p>Word-like column layout: chief complaint and history in one column, examinations and diagnosis in another, with content flowing automatically across columns and relayout on zoom or page-width change.</p><h3 id="🖼-text-wrapping-around-images-554" tabindex="-1">🖼 Text Wrapping Around Images (<a href="https://github.com/Hufe921/canvas-editor/issues/554" target="_blank" rel="noreferrer">#554</a>) <a class="header-anchor" href="#🖼-text-wrapping-around-images-554" aria-label="Permalink to &quot;🖼 Text Wrapping Around Images ([#554](https://github.com/Hufe921/canvas-editor/issues/554))&quot;">​</a></h3><p>Floating images support four-side text wrapping — drop a handwritten signature image into a paragraph and text flows around it, adjusting in real time as content changes.</p><h3 id="📏-rulers-438" tabindex="-1">📏 Rulers (<a href="https://github.com/Hufe921/canvas-editor/issues/438" target="_blank" rel="noreferrer">#438</a>) <a class="header-anchor" href="#📏-rulers-438" aria-label="Permalink to &quot;📏 Rulers ([#438](https://github.com/Hufe921/canvas-editor/issues/438))&quot;">​</a></h3><p>Horizontal + vertical rulers with zoom-synced scales; margins and indents at a glance — no more guessing for alignment.</p><h3 id="🔢-multi-level-ordered-lists-440" tabindex="-1">🔢 Multi-level Ordered Lists (<a href="https://github.com/Hufe921/canvas-editor/issues/440" target="_blank" rel="noreferrer">#440</a>) <a class="header-anchor" href="#🔢-multi-level-ordered-lists-440" aria-label="Permalink to &quot;🔢 Multi-level Ordered Lists ([#440](https://github.com/Hufe921/canvas-editor/issues/440))&quot;">​</a></h3><p>Nested numbering stays consistent: &quot;1. Hypertension&quot; parents &quot;1. Grade 1 hypertension / 2. Primary hypertension,&quot; and all levels renumber automatically as items are added or removed.</p><h3 id="📑-area-sub-documents" tabindex="-1">📑 Area Sub-documents <a class="header-anchor" href="#📑-area-sub-documents" aria-label="Permalink to &quot;📑 Area Sub-documents&quot;">​</a></h3><p>A document can be divided into multiple <strong>independent areas</strong>: main record + supplementary record, each with its own editing context, placeholder, readonly and visibility rules — areas can even live inside table cells (<a href="https://github.com/Hufe921/canvas-editor/issues/1317" target="_blank" rel="noreferrer">#1317</a>). The <code>executeInsertArea</code> / <code>executeLocationArea</code> / <code>executeSetAreaValue</code> / <code>executeDeleteArea</code> API family makes &quot;one document, many governed sections&quot; possible.</p><h3 id="⏺-macro-recording-playback-478" tabindex="-1">⏺ Macro Recording &amp; Playback (<a href="https://github.com/Hufe921/canvas-editor/issues/478" target="_blank" rel="noreferrer">#478</a>) <a class="header-anchor" href="#⏺-macro-recording-playback-478" aria-label="Permalink to &quot;⏺ Macro Recording &amp; Playback ([#478](https://github.com/Hufe921/canvas-editor/issues/478))&quot;">​</a></h3><p>Record a sequence of operations (insert controls, set styles, fill data) and replay it with one click — great for batch generation and automated testing.</p><h3 id="🆚-document-compare-api-1024" tabindex="-1">🆚 Document Compare API (<a href="https://github.com/Hufe921/canvas-editor/issues/1024" target="_blank" rel="noreferrer">#1024</a>) <a class="header-anchor" href="#🆚-document-compare-api-1024" aria-label="Permalink to &quot;🆚 Document Compare API ([#1024](https://github.com/Hufe921/canvas-editor/issues/1024))&quot;">​</a></h3><p>A new compare capability makes differences between two document versions clear at a glance; together with Trace Mode it forms a basic review loop.</p><h2 id="📅-the-last-three-years-2023-08-→-2026-07" tabindex="-1">📅 The Last Three Years (2023.08 → 2026.07) <a class="header-anchor" href="#📅-the-last-three-years-2023-08-→-2026-07" aria-label="Permalink to &quot;📅 The Last Three Years (2023.08 → 2026.07)&quot;">​</a></h2><p>1.0 didn&#39;t happen overnight: <strong>781 commits, 256 fixes, and 479 issues handled</strong> in three years. Highlights by theme:</p><h3 id="tables-the-most-invested-line" tabindex="-1">Tables (the most invested line) <a class="header-anchor" href="#tables-the-most-invested-line" aria-label="Permalink to &quot;Tables (the most invested line)&quot;">​</a></h3><ul><li>Table pagination (<a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a>) ⭐</li><li>Table width auto-fit to content and page (<a href="https://github.com/Hufe921/canvas-editor/issues/1387" target="_blank" rel="noreferrer">#1387</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1453" target="_blank" rel="noreferrer">#1453</a>)</li><li>Table nesting (<a href="https://github.com/Hufe921/canvas-editor/issues/650" target="_blank" rel="noreferrer">#650</a>), cell splitting (<a href="https://github.com/Hufe921/canvas-editor/issues/826" target="_blank" rel="noreferrer">#826</a>), content-preserving merge (<a href="https://github.com/Hufe921/canvas-editor/issues/932" target="_blank" rel="noreferrer">#932</a>)</li><li>Quick row/column tools, dashed borders (<a href="https://github.com/Hufe921/canvas-editor/issues/858" target="_blank" rel="noreferrer">#858</a>), border color &amp; width (<a href="https://github.com/Hufe921/canvas-editor/issues/897" target="_blank" rel="noreferrer">#897</a>)</li><li>Tables allowed beyond text boundaries (<a href="https://github.com/Hufe921/canvas-editor/issues/1232" target="_blank" rel="noreferrer">#1232</a>), auto-generated colgroup (<a href="https://github.com/Hufe921/canvas-editor/issues/1404" target="_blank" rel="noreferrer">#1404</a>)</li></ul><h3 id="controls-form-ification" tabindex="-1">Controls (form-ification) <a class="header-anchor" href="#controls-form-ification" aria-label="Permalink to &quot;Controls (form-ification)&quot;">​</a></h3><ul><li>Cascade &amp; validation (<a href="https://github.com/Hufe921/canvas-editor/issues/671" target="_blank" rel="noreferrer">#671</a>), nesting (<a href="https://github.com/Hufe921/canvas-editor/issues/425" target="_blank" rel="noreferrer">#425</a>)</li><li>Number control with built-in calculator (<a href="https://github.com/Hufe921/canvas-editor/issues/925" target="_blank" rel="noreferrer">#925</a>), multi-select &amp; input Select (<a href="https://github.com/Hufe921/canvas-editor/issues/518" target="_blank" rel="noreferrer">#518</a>), year/month date panel (<a href="https://github.com/Hufe921/canvas-editor/issues/1256" target="_blank" rel="noreferrer">#1256</a>)</li><li>Control grouping (<a href="https://github.com/Hufe921/canvas-editor/issues/1259" target="_blank" rel="noreferrer">#1259</a>), design mode (<a href="https://github.com/Hufe921/canvas-editor/issues/795" target="_blank" rel="noreferrer">#795</a>), batch property setting (<a href="https://github.com/Hufe921/canvas-editor/issues/1037" target="_blank" rel="noreferrer">#1037</a>)</li></ul><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><ul><li>Multi-column (<a href="https://github.com/Hufe921/canvas-editor/issues/1237" target="_blank" rel="noreferrer">#1237</a>), image wrapping (<a href="https://github.com/Hufe921/canvas-editor/issues/554" target="_blank" rel="noreferrer">#554</a>), rulers (<a href="https://github.com/Hufe921/canvas-editor/issues/438" target="_blank" rel="noreferrer">#438</a>)</li><li>Multi-level ordered lists (<a href="https://github.com/Hufe921/canvas-editor/issues/440" target="_blank" rel="noreferrer">#440</a>), page borders, line numbers (<a href="https://github.com/Hufe921/canvas-editor/issues/734" target="_blank" rel="noreferrer">#734</a>)</li><li>Per-page header/footer hiding (<a href="https://github.com/Hufe921/canvas-editor/issues/778" target="_blank" rel="noreferrer">#778</a>), editable headers/footers</li></ul><h3 id="area-sub-documents" tabindex="-1">Area Sub-documents <a class="header-anchor" href="#area-sub-documents" aria-label="Permalink to &quot;Area Sub-documents&quot;">​</a></h3><ul><li>Area placeholder (<a href="https://github.com/Hufe921/canvas-editor/issues/1076" target="_blank" rel="noreferrer">#1076</a>), deletable/hidable areas (<a href="https://github.com/Hufe921/canvas-editor/issues/1014" target="_blank" rel="noreferrer">#1014</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1139" target="_blank" rel="noreferrer">#1139</a>)</li><li>Area API family, areas inside table cells (<a href="https://github.com/Hufe921/canvas-editor/issues/1317" target="_blank" rel="noreferrer">#1317</a>)</li></ul><h3 id="productivity" tabindex="-1">Productivity <a class="header-anchor" href="#productivity" aria-label="Permalink to &quot;Productivity&quot;">​</a></h3><ul><li>Macros (<a href="https://github.com/Hufe921/canvas-editor/issues/478" target="_blank" rel="noreferrer">#478</a>), format painter improvements (<a href="https://github.com/Hufe921/canvas-editor/issues/446" target="_blank" rel="noreferrer">#446</a>)</li><li>Regex search (<a href="https://github.com/Hufe921/canvas-editor/issues/1308" target="_blank" rel="noreferrer">#1308</a>), search within selection (<a href="https://github.com/Hufe921/canvas-editor/issues/1336" target="_blank" rel="noreferrer">#1336</a>), case-insensitive search (<a href="https://github.com/Hufe921/canvas-editor/issues/1316" target="_blank" rel="noreferrer">#1316</a>)</li><li>Image cropping (<a href="https://github.com/Hufe921/canvas-editor/issues/1327" target="_blank" rel="noreferrer">#1327</a>), image captions (<a href="https://github.com/Hufe921/canvas-editor/issues/1326" target="_blank" rel="noreferrer">#1326</a>), magnifier (<a href="https://github.com/Hufe921/canvas-editor/issues/1391" target="_blank" rel="noreferrer">#1391</a>), graffiti mode (<a href="https://github.com/Hufe921/canvas-editor/issues/992" target="_blank" rel="noreferrer">#992</a>)</li></ul><h3 id="enterprise" tabindex="-1">Enterprise <a class="header-anchor" href="#enterprise" aria-label="Permalink to &quot;Enterprise&quot;">​</a></h3><ul><li>Trace mode (<a href="https://github.com/Hufe921/canvas-editor/issues/312" target="_blank" rel="noreferrer">#312</a>), document compare (<a href="https://github.com/Hufe921/canvas-editor/issues/1024" target="_blank" rel="noreferrer">#1024</a>)</li><li>Watermarks: image watermark (<a href="https://github.com/Hufe921/canvas-editor/issues/1043" target="_blank" rel="noreferrer">#1043</a>), layer configuration (<a href="https://github.com/Hufe921/canvas-editor/issues/1386" target="_blank" rel="noreferrer">#1386</a>), tiling (<a href="https://github.com/Hufe921/canvas-editor/issues/665" target="_blank" rel="noreferrer">#665</a>)</li><li>Accessibility (screen readers) (<a href="https://github.com/Hufe921/canvas-editor/issues/1420" target="_blank" rel="noreferrer">#1420</a>), i18n (<a href="https://github.com/Hufe921/canvas-editor/issues/1159" target="_blank" rel="noreferrer">#1159</a>)</li><li>Printing: offscreen print, filtering empty controls/hidden elements (<a href="https://github.com/Hufe921/canvas-editor/issues/1429" target="_blank" rel="noreferrer">#1429</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1385" target="_blank" rel="noreferrer">#1385</a> <a href="https://github.com/Hufe921/canvas-editor/issues/1410" target="_blank" rel="noreferrer">#1410</a>)</li></ul><h2 id="🐛-bug-fixes-since-0-9-137" tabindex="-1">🐛 Bug Fixes (since 0.9.137) <a class="header-anchor" href="#🐛-bug-fixes-since-0-9-137" aria-label="Permalink to &quot;🐛 Bug Fixes (since 0.9.137)&quot;">​</a></h2><ul><li>Fixed incorrect row-height calculation for tall content with <code>rowspan</code> cells</li><li>Fixed control member state sync and highlight errors on cascade restore</li><li>Fixed controls not being re-activated before input when inactive <a href="https://github.com/Hufe921/canvas-editor/issues/1443" target="_blank" rel="noreferrer">#1443</a></li></ul><p>See <a href="https://github.com/Hufe921/canvas-editor/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a> for the full commit list.</p><h2 id="📦-upgrading" tabindex="-1">📦 Upgrading <a class="header-anchor" href="#📦-upgrading" aria-label="Permalink to &quot;📦 Upgrading&quot;">​</a></h2><p>If you&#39;re on 0.9.x:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @hufe921/canvas-editor@1.0.0</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @hufe921/canvas-editor@1.0.0</span></span></code></pre></div><p><strong>1.0.0 introduces no breaking API changes</strong> — most users can upgrade seamlessly. Two things to note:</p><ol><li><strong>Table pagination behavior changed</strong>: cross-page tables render differently (more correctly) than in 0.9.x. Update visual snapshot baselines if your tests assert on them.</li><li><strong>Control cascade validation is opt-in</strong>: existing controls are unaffected unless explicitly configured.</li></ol><p>Questions? <a href="https://github.com/Hufe921/canvas-editor/discussions" target="_blank" rel="noreferrer">Discussions</a> · Bugs? <a href="https://github.com/Hufe921/canvas-editor/issues/new?template=bug_report.yml" target="_blank" rel="noreferrer">Issues</a></p><h2 id="🗺-roadmap" tabindex="-1">🗺 Roadmap <a class="header-anchor" href="#🗺-roadmap" aria-label="Permalink to &quot;🗺 Roadmap&quot;">​</a></h2><p>After 1.0, the focus shifts from &quot;filling core gaps&quot; to &quot;expanding the ecosystem&quot;:</p><ol><li><strong>Large-document rendering performance</strong>: measurement and painting optimizations to keep editing smooth in very long documents</li><li><strong>Renderer abstraction</strong>: decouple the rendering layer from the core, so the same document model can target SVG, PDF, DOM, and more</li><li><strong>Multi-cursor &amp; multi-selection</strong>: multiple carets and selections, laying the groundwork for collaboration and batch operations</li><li><strong>Collaborative editing</strong>: real-time multi-user collaboration, cursor sync, and conflict resolution (evaluating Yjs / CRDT)</li></ol><p>+1 the issues you care about — <strong>the most requested features get scheduled first</strong>.</p><h2 id="✍️-by-the-numbers" tabindex="-1">✍️ By the Numbers <a class="header-anchor" href="#✍️-by-the-numbers" aria-label="Permalink to &quot;✍️ By the Numbers&quot;">​</a></h2><p>Canvas Editor is a personal project I maintain in my spare time. Over the past 1,723 days:</p><ul><li><p><strong>1,460 commits</strong> — 781 of them in the last three years; <strong>479 issues</strong> handled, <strong>139 releases</strong> shipped</p></li><li><p>Peak commit hours are <strong>9–10 PM</strong> (224 + 150) — the hours after work</p></li><li><p><strong>162 commits landed after 10 PM</strong>, <strong>245 on weekends</strong></p><p>1.0 also belongs to the community: the final approach for <a href="https://github.com/Hufe921/canvas-editor/issues/41" target="_blank" rel="noreferrer">#41</a> absorbed ideas from several community PRs and was publicly validated on a POC branch; AI coding tools helped accelerate the final refactor. That&#39;s the fun of open source — an issue open for four years, finally pushed across the finish line by many people together.</p></li></ul><p>If this project has helped you, a Star or a share is great support.</p><h2 id="💛-personal-sponsorship" tabindex="-1">💛 Personal Sponsorship <a class="header-anchor" href="#💛-personal-sponsorship" aria-label="Permalink to &quot;💛 Personal Sponsorship&quot;">​</a></h2><p>Canvas Editor is a personal open-source project, built in spare time over nearly five years, and it remains free under the MIT license. 1.0 is a milestone, but also a starting point — every item on the roadmap above requires significant investment.</p><p>If you or your company use Canvas Editor and want to see it thrive:</p><ul><li><strong>GitHub Sponsors</strong>: <a href="https://hufe.club/donate.jpg" target="_blank" rel="noreferrer">https://hufe.club/donate.jpg</a></li></ul><p>Even a small one-time sponsorship is direct encouragement. And of course, stars, shares, thoughtful issues and PRs are just as valuable.</p><h2 id="🙏-acknowledgements" tabindex="-1">🙏 Acknowledgements <a class="header-anchor" href="#🙏-acknowledgements" aria-label="Permalink to &quot;🙏 Acknowledgements&quot;">​</a></h2><p>Thanks to everyone who filed issues, sent PRs, answered questions, wrote about the project, or quietly starred it over the past four years.</p><p>I hope to keep walking Canvas Editor&#39;s next chapter together with you.</p><hr><p align="center"><strong>Canvas Editor 1.0.0</strong><br><a href="https://github.com/Hufe921/canvas-editor">⭐ GitHub</a> · <a href="https://hufe.club/canvas-editor">🚀 Live Demo</a> · <a href="https://hufe.club/canvas-editor-docs">📖 Docs</a> · <a href="https://hufe.club/donate.jpg">💛 Sponsor</a></p>',196)])])}const p=a(o,[["render",i]]);export{g as __pageData,p as default};
